/*
 * Site search: loaded on first open by site.js.
 *
 * Index: /assets/js/data/search.json (generated by _plugins/search_index.rb)
 *   t title · u url · d date · k kind (post|deep-dive|page) · c categories
 *   g tags · s summary · b body text (truncated)
 *
 * Every query term must match somewhere in an entry (AND); matches are
 * weighted title > tag > category > summary > body, and ties go to newer posts.
 */

const INDEX_URL = new URL("data/search.json", import.meta.url).href;
const RECENT_KEY = "recent-searches";
const MAX_RESULTS = 20;
const MAX_PER_GROUP = 6;
// Result types, in display order when results are grouped.
const TYPES = [
  { id: "course", label: "Courses" },
  { id: "post", label: "Articles" },
  { id: "deep-dive", label: "Course notes" },
  { id: "page", label: "Pages" },
];
const MAX_RECENT = 5;
const SUGGESTIONS = ["kubernetes", "python", "idempotency", "canary", "observability", "asyncio"];

let indexPromise = null;
let attached = false;

const escapeHtml = (s) => s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const fold = (s) => s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "");

function loadIndex() {
  if (!indexPromise) {
    indexPromise = fetch(INDEX_URL, { credentials: "same-origin" })
      .then((res) => {
        if (!res.ok) throw new Error(`Search index returned HTTP ${res.status}`);
        return res.json();
      })
      .then((entries) => entries.map((e) => ({
        ...e,
        _t: fold(e.t), _g: e.g.map(fold), _c: e.c.map(fold), _s: fold(e.s || ""), _b: fold(e.b || ""),
      })))
      .catch((error) => { indexPromise = null; throw error; });
  }
  return indexPromise;
}

const recent = {
  list() {
    try { return JSON.parse(localStorage.getItem(RECENT_KEY)) || []; } catch { return []; }
  },
  add(query) {
    const q = query.trim();
    if (q.length < 2) return;
    const next = [q, ...this.list().filter((r) => r.toLowerCase() !== q.toLowerCase())].slice(0, MAX_RECENT);
    try { localStorage.setItem(RECENT_KEY, JSON.stringify(next)); } catch { /* storage unavailable */ }
  },
  clear() {
    try { localStorage.removeItem(RECENT_KEY); } catch { /* storage unavailable */ }
  },
};

function score(entry, terms) {
  let total = 0;
  for (const term of terms) {
    let s = 0;
    const titleAt = entry._t.indexOf(term);
    if (titleAt !== -1) s += 12 + (titleAt === 0 || entry._t[titleAt - 1] === " " ? 6 : 0);
    if (entry._g.some((g) => g === term)) s += 9;
    else if (entry._g.some((g) => g.includes(term))) s += 5;
    if (entry._c.some((c) => c.includes(term))) s += 5;
    if (entry._s.includes(term)) s += 3;
    if (entry._b.includes(term)) s += 1;
    if (s === 0) return 0; // every term must match
    total += s;
  }
  return total + (entry.k === "course" ? 3 : entry.k === "post" ? 1 : 0);
}

function search(entries, query) {
  const terms = fold(query).split(/\s+/).filter(Boolean);
  if (!terms.length) return { terms, results: [] };
  const results = entries
    .map((entry) => ({ entry, score: score(entry, terms) }))
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score || (b.entry.d || "").localeCompare(a.entry.d || ""))
    .map((r) => r.entry);
  return { terms, results };
}

function highlight(text, terms) {
  const safe = escapeHtml(text);
  if (!terms.length) return safe;
  const re = new RegExp(`(${terms.map((t) => escapeRe(escapeHtml(t))).join("|")})`, "gi");
  return safe.replace(re, "<mark>$1</mark>");
}

function snippet(entry, terms) {
  const source = entry.s && terms.some((t) => entry._s.includes(t)) ? entry.s : entry.b || entry.s || "";
  const folded = fold(source);
  const at = terms.map((t) => folded.indexOf(t)).filter((i) => i >= 0).sort((a, b) => a - b)[0];
  if (at === undefined) return source.slice(0, 160);
  const start = Math.max(0, at - 60);
  const text = source.slice(start, start + 170);
  return (start > 0 ? "…" : "") + text + (start + 170 < source.length ? "…" : "");
}

function metaLine(entry) {
  const kind = { post: "Article", course: "Course", "deep-dive": "Course notes", page: "Page" }[entry.k] || "Page";
  const parts = [kind];
  if (entry.c.length) parts.push(entry.c[0]);
  if (entry.d) {
    const date = new Date(`${entry.d}T00:00:00Z`);
    parts.push(date.toLocaleDateString("en", { month: "short", year: "numeric", timeZone: "UTC" }));
  }
  return parts.join(" · ");
}

export function attach(dialog) {
  const input = dialog.querySelector("#search-input");
  const view = dialog.querySelector("[data-search-view]");
  const status = dialog.querySelector("[data-search-status]");

  if (attached) {
    input.value = "";
    input.focus();
    renderIdle();
    return;
  }
  // First open: the module loads asynchronously, so the reader may already
  // have typed. Keep that text and search it once we are wired up.
  attached = true;
  input.focus();

  let entries = null;
  let active = -1;
  let filter = "all";
  let timer = null;

  function openResult(option, newTab) {
    recent.add(input.value);
    const href = option.dataset.href;
    if (newTab) window.open(href, "_blank", "noopener");
    else window.location.href = href;
  }

  function options() {
    return Array.from(view.querySelectorAll("[role=option]"));
  }

  function setActive(index) {
    const opts = options();
    if (!opts.length) { active = -1; input.removeAttribute("aria-activedescendant"); return; }
    active = (index + opts.length) % opts.length;
    opts.forEach((o, i) => o.setAttribute("aria-selected", String(i === active)));
    input.setAttribute("aria-activedescendant", opts[active].id);
    opts[active].scrollIntoView({ block: "nearest" });
  }

  function chips(title, values, { clearable = false } = {}) {
    if (!values.length) return "";
    const buttons = values.map((v) => `<button type="button" data-query="${escapeHtml(v)}">${escapeHtml(v)}</button>`).join("");
    const clear = clearable ? ` <button type="button" class="link-button" data-clear-recent>Clear</button>` : "";
    return `<p class="search-dialog__group eyebrow">${escapeHtml(title)}${clear}</p><div class="search-chips">${buttons}</div>`;
  }

  function renderIdle() {
    input.setAttribute("aria-expanded", "false");
    input.removeAttribute("aria-controls");
    input.removeAttribute("aria-activedescendant");
    view.innerHTML = chips("Recent searches", recent.list(), { clearable: true }) + chips("Try searching for", SUGGESTIONS);
    status.textContent = "";
  }

  function renderLoading() {
    view.innerHTML = `<div class="search-dialog__group" aria-hidden="true">${
      '<span class="skeleton" style="width:70%"></span><br><span class="skeleton" style="width:45%"></span><br>'.repeat(3)}</div>`;
    status.textContent = "Loading search index";
  }

  function renderError() {
    view.innerHTML = `<div class="search-dialog__group"><p>Search is unavailable right now.</p>
      <p class="muted">Check your connection, then <button type="button" class="link-button" data-retry>try again</button>.
      You can also browse the <a href="/tabs/archives/">archive</a>.</p></div>`;
    status.textContent = "Search is unavailable";
  }

  function filterBar(counts, total) {
    const button = (id, label, n) =>
      `<button type="button" data-type="${id}" aria-pressed="${filter === id}">${escapeHtml(label)} <span>${n}</span></button>`;
    const buttons = [button("all", "All", total)]
      .concat(TYPES.filter((t) => counts[t.id]).map((t) => button(t.id, t.label, counts[t.id])));
    return `<div class="search-filters" role="group" aria-label="Filter results by type">${buttons.join("")}</div>`;
  }

  function option(entry, i, terms) {
    // Options must not contain interactive elements (ARIA listbox rules), so a
    // result is a plain option carrying its URL; activation is handled below.
    return `<div role="option" id="search-opt-${i}" aria-selected="false" data-href="${escapeHtml(entry.u)}">
        <div class="search-result">
          <div class="search-result__title">${highlight(entry.t, terms)}</div>
          <div class="search-result__meta">${escapeHtml(metaLine(entry))}</div>
          <div class="search-result__snippet">${highlight(snippet(entry, terms), terms)}</div>
        </div>
      </div>`;
  }

  function renderResults(query) {
    const { terms, results } = search(entries, query);
    active = -1;
    if (!results.length) {
      input.setAttribute("aria-expanded", "false");
      input.removeAttribute("aria-controls");
      input.removeAttribute("aria-activedescendant");
      view.innerHTML = `<div class="search-dialog__group"><p><strong>No results for “${escapeHtml(query)}”.</strong></p>
        <p class="muted">Try fewer or broader words, or browse <a href="/tabs/categories/">topics</a> and <a href="/tabs/tags/">tags</a>.</p></div>` +
        chips("Popular searches", SUGGESTIONS);
      status.textContent = `No results for ${query}`;
      return;
    }

    const counts = {};
    results.forEach((e) => { counts[e.k] = (counts[e.k] || 0) + 1; });
    if (filter !== "all" && !counts[filter]) filter = "all";

    // "All": grouped by type, a few per group. A type filter: one flat list.
    const groups = filter === "all"
      ? TYPES.filter((t) => counts[t.id]).map((t) => ({ ...t, items: results.filter((e) => e.k === t.id).slice(0, MAX_PER_GROUP) }))
      : [{ ...TYPES.find((t) => t.id === filter), items: results.filter((e) => e.k === filter).slice(0, MAX_RESULTS) }];

    let i = 0;
    const body = groups.map((g) => `
      <div role="group" aria-labelledby="search-group-${g.id}">
        <div class="search-dialog__group eyebrow" id="search-group-${g.id}" role="presentation">${escapeHtml(g.label)}</div>
        ${g.items.map((entry) => option(entry, i++, terms)).join("")}
      </div>`).join("");

    const shown = i;
    const count = `${results.length} ${results.length === 1 ? "result" : "results"}`;
    view.innerHTML = filterBar(counts, results.length) +
      `<div class="search-dialog__results" id="search-results" role="listbox" aria-label="Search results">${body}</div>`;
    input.setAttribute("aria-expanded", "true");
    input.setAttribute("aria-controls", "search-results");
    status.textContent = shown < results.length ? `${count}, showing ${shown}` : count;
    setActive(0);
  }

  async function run() {
    const query = input.value.trim();
    if (!query) { renderIdle(); return; }
    if (!entries) {
      renderLoading();
      try {
        entries = await loadIndex();
      } catch (error) {
        console.error(error);
        renderError();
        return;
      }
    }
    if (input.value.trim() === query) renderResults(query);
  }

  input.addEventListener("input", () => {
    clearTimeout(timer);
    timer = setTimeout(run, 60);
  });

  input.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown") { event.preventDefault(); setActive(active + 1); }
    else if (event.key === "ArrowUp") { event.preventDefault(); setActive(active - 1); }
    else if (event.key === "Enter") {
      const option = options()[active];
      if (option) {
        event.preventDefault();
        openResult(option, event.metaKey || event.ctrlKey);
      }
    }
  });

  view.addEventListener("click", (event) => {
    const type = event.target.closest("[data-type]");
    if (type) {
      filter = type.dataset.type;
      renderResults(input.value.trim());
      view.querySelector(`[data-type="${filter}"]`)?.focus();
      return;
    }
    const chip = event.target.closest("[data-query]");
    if (chip) {
      input.value = chip.dataset.query;
      input.focus();
      run();
      return;
    }
    if (event.target.closest("[data-clear-recent]")) {
      recent.clear();
      renderIdle();
      input.focus();
      return;
    }
    if (event.target.closest("[data-retry]")) {
      run();
      return;
    }
    const option = event.target.closest("[role=option]");
    if (option) openResult(option, event.metaKey || event.ctrlKey);
  });

  // Middle-click opens a result in a new tab, like a normal link.
  view.addEventListener("auxclick", (event) => {
    const option = event.button === 1 && event.target.closest("[role=option]");
    if (option) { event.preventDefault(); openResult(option, true); }
  });

  view.addEventListener("mousemove", (event) => {
    const option = event.target.closest("[role=option]");
    if (!option) return;
    const index = options().indexOf(option);
    if (index !== active) setActive(index);
  });

  // Warm the index in the background so the first keystroke is instant.
  loadIndex().then((e) => { entries = e; }).catch(() => { /* surfaced on first query */ });
  if (input.value.trim()) run(); else renderIdle();
}
